    # taboo
    S = ctx.new_page(); route(S, []); S.on("pageerror", lambda e: serr.append(str(e)))
    S.goto("https://sltimms90.github.io/lesson-games/"); S.goto(links["g4"]); S.reload(); S.wait_for_selector("[data-a=s-start]"); S.wait_for_timeout(400); S.click("[data-a=s-start]"); T.wait_for_timeout(1200)
